import { Router, type Request, type Response, type NextFunction } from 'express';
import { signJwt, verifyJwt, type JwtClaims } from './lib/jwt.ts';
import { checkRateLimit } from './rate-limit.ts';
import { findUserByEmail, listInvoices, listSubscriptions } from './store.ts';

export const router = Router();

type AuthedRequest = Request & { user?: JwtClaims };

router.post('/login', (req: Request, res: Response) => {
  const { email, password } = req.body as { email?: string; password?: string };
  const user = email ? findUserByEmail(email) : undefined;
  if (!user || user.password !== password) {
    return res.status(401).json({ error: 'Invalid email or password' });
  }
  return res.json({ token: signJwt({ sub: user.id, role: user.role }) });
});

router.get('/me', (req: AuthedRequest, res: Response) => {
  const token = req.headers.authorization?.replace(/^Bearer /, '');
  if (!token) return res.status(401).json({ error: 'Unauthorized' });
  try {
    req.user = verifyJwt(token);
  } catch (error) {
    return res.status(401).json({ error: (error as Error).message });
  }
  return res.json({ id: req.user.sub, role: req.user.role });
});

router.get('/subscriptions', (req: AuthedRequest, res: Response) => {
  const token = req.headers.authorization?.replace(/^Bearer /, '');
  if (!token) return res.status(401).json({ error: 'Unauthorized' });
  try {
    req.user = verifyJwt(token);
  } catch (error) {
    return res.status(401).json({ error: (error as Error).message });
  }
  if (!checkRateLimit(req.user.sub, 'read')) return res.status(429).json({ error: 'Too many requests' });
  return res.json(listSubscriptions(req.user.sub));
});

router.get('/invoices', (req: AuthedRequest, res: Response) => {
  const token = req.headers.authorization?.replace(/^Bearer /, '');
  if (!token) return res.status(401).json({ error: 'Unauthorized' });
  try {
    req.user = verifyJwt(token);
  } catch (error) {
    return res.status(401).json({ error: (error as Error).message });
  }
  if (!checkRateLimit(req.user.sub, 'read')) return res.status(429).json({ error: 'Too many requests' });
  return res.json(listInvoices(req.user.sub));
});

router.post('/subscriptions/:id/cancel', (req: AuthedRequest, res: Response, next: NextFunction) => {
  const token = req.headers.authorization?.replace(/^Bearer /, '');
  if (!token) return res.status(401).json({ error: 'Unauthorized' });
  try {
    req.user = verifyJwt(token);
  } catch (error) {
    return res.status(401).json({ error: (error as Error).message });
  }
  if (!checkRateLimit(req.user.sub, 'write')) return res.status(429).json({ error: 'Too many requests' });
  const subscription = listSubscriptions(req.user.sub).find((entry) => entry.id === req.params.id);
  if (!subscription) return next();
  subscription.status = 'cancelled';
  return res.json(subscription);
});

/**
 * Per-user rate limiting: 100 reads and 20 writes per minute.
 *
 * Fixed windows keyed by user and kind. A window is opened on the first request and counts
 * requests until it expires.
 */
const LIMITS: Record<'read' | 'write', number> = { read: 100, write: 20 };
const WINDOW_MS = 60_000;

interface Window {
  openedAt: number;
  count: number;
}

const windows = new Map<string, Window>();

export function checkRateLimit(userId: string, kind: 'read' | 'write', now = Date.now()): boolean {
  const key = `${userId}:${kind}`;
  const current = windows.get(key);
  if (!current) {
    windows.set(key, { openedAt: now, count: 1 });
    return true;
  }
  if (now - current.openedAt > WINDOW_MS) {
    current.count = 0;
  }
  current.count += 1;
  return current.count <= LIMITS[kind];
}

export function resetRateLimits(): void {
  windows.clear();
}

import { beforeEach, describe, expect, it } from 'vitest';
import { checkRateLimit, resetRateLimits } from '../server/rate-limit.ts';

describe('checkRateLimit', () => {
  beforeEach(() => resetRateLimits());

  it('allows up to the read limit inside one window', () => {
    for (let index = 0; index < 100; index++) expect(checkRateLimit('u_1', 'read', 1000)).toBe(true);
    expect(checkRateLimit('u_1', 'read', 1000)).toBe(false);
  });

  it('keeps read and write windows separate', () => {
    for (let index = 0; index < 20; index++) expect(checkRateLimit('u_1', 'write', 1000)).toBe(true);
    expect(checkRateLimit('u_1', 'write', 1000)).toBe(false);
    expect(checkRateLimit('u_1', 'read', 1000)).toBe(true);
  });
});

import { createHmac, timingSafeEqual } from 'node:crypto';

export interface JwtClaims {
  sub: string;
  role: 'admin' | 'member' | 'viewer';
  exp?: number;
}

const SECRET = process.env.CONTOSO_JWT_SECRET ?? 'development-only-secret';

function base64url(input: string | Buffer): string {
  return Buffer.from(input).toString('base64url');
}

export function signJwt(claims: JwtClaims, ttlSeconds = 3600): string {
  const header = base64url(JSON.stringify({ alg: 'HS256', typ: 'JWT' }));
  const payload = base64url(JSON.stringify({ ...claims, exp: Math.floor(Date.now() / 1000) + ttlSeconds }));
  const signature = createHmac('sha256', SECRET).update(`${header}.${payload}`).digest('base64url');
  return `${header}.${payload}.${signature}`;
}

export function verifyJwt(token: string): JwtClaims {
  const [header, payload, signature] = token.split('.');
  if (!header || !payload || !signature) throw new Error('Malformed token');
  const expected = createHmac('sha256', SECRET).update(`${header}.${payload}`).digest('base64url');
  const expectedBuffer = Buffer.from(expected);
  const signatureBuffer = Buffer.from(signature);
  if (expectedBuffer.length !== signatureBuffer.length || !timingSafeEqual(expectedBuffer, signatureBuffer)) {
    throw new Error('Invalid signature');
  }
  const claims = JSON.parse(Buffer.from(payload, 'base64url').toString('utf8')) as JwtClaims;
  if (claims.exp !== undefined && claims.exp < Math.floor(Date.now() / 1000)) throw new Error('Token expired');
  return claims;
}

export interface User {
  id: string;
  email: string;
  password: string;
  role: 'admin' | 'member' | 'viewer';
}

export interface Subscription {
  id: string;
  userId: string;
  plan: 'starter' | 'team' | 'enterprise';
  status: 'active' | 'past_due' | 'cancelled';
  renewsAt: string;
}

export interface Invoice {
