import { useEffect, useState } from 'react';
import { apiFetch } from './lib/http-client';
import { LiveUpdates } from './lib/websocket';

interface Subscription {
  id: string;
  plan: string;
  status: string;
  renewsAt: string;
}

export function App() {
  const [subscriptions, setSubscriptions] = useState<Subscription[]>([]);
  const [status, setStatus] = useState('loading');

  useEffect(() => {
    apiFetch<Subscription[]>('/subscriptions')
      .then((rows) => { setSubscriptions(rows); setStatus('ready'); })
      .catch(() => setStatus('error'));
    const live = new LiveUpdates(`ws://${window.location.host}/live`);
    live.connect();
    const unsubscribe = live.subscribe((event) => {
      const update = JSON.parse(event.data) as Subscription;
      setSubscriptions((current) => current.map((row) => (row.id === update.id ? update : row)));
    });
    return () => { unsubscribe(); live.close(); };
  }, []);

  return (
    <main>
      <h1>Contoso</h1>
      <p>{status === 'loading' ? 'Loading subscriptions' : `${subscriptions.length} subscriptions`}</p>
      <ul>
        {subscriptions.map((row) => (
          <li key={row.id}>{row.plan} ({row.status}) renews {row.renewsAt}</li>
        ))}
      </ul>
    </main>
  );
}

export interface RetryOptions {
  maxRetries: number;
  backoff: 'linear' | 'exponential';
  baseDelayMs?: number;
}

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

export async function retryWithBackoff<T>(request: () => Promise<T>, options: RetryOptions): Promise<T> {
  const baseDelayMs = options.baseDelayMs ?? 200;
  let attempt = 0;
  for (;;) {
    try {
      return await request();
    } catch (error) {
      attempt += 1;
      if (attempt > options.maxRetries) throw error;
      const delay = options.backoff === 'exponential' ? baseDelayMs * 2 ** (attempt - 1) : baseDelayMs * attempt;
      await sleep(delay);
    }
  }
}

export async function apiFetch<T>(path: string, init?: RequestInit): Promise<T> {
  return retryWithBackoff(async () => {
    const response = await fetch(`/api${path}`, init);
    if (!response.ok) throw new Error(`${response.status} ${response.statusText}`);
    return (await response.json()) as T;
  }, { maxRetries: 3, backoff: 'exponential' });
}

type Listener = (event: MessageEvent) => void;

/**
 * The live-updates socket for the dashboard. Opens once; a dropped connection is reported to
 * the listeners and never reopened, which is the gap the reconnection work closes.
 */
export class LiveUpdates {
  private socket: WebSocket | null = null;
  private readonly listeners = new Set<Listener>();

  constructor(private readonly url: string) {}

  connect(): void {
    this.socket = new WebSocket(this.url);
    this.socket.addEventListener('message', (event) => {
      this.listeners.forEach((listener) => listener(event));
    });
    this.socket.addEventListener('close', () => {
      this.socket = null;
    });
  }

  subscribe(listener: Listener): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  send(payload: unknown): void {
    if (!this.socket || this.socket.readyState !== WebSocket.OPEN) {
      throw new Error('Live updates are not connected');
    }
    this.socket.send(JSON.stringify(payload));
  }

  close(): void {
    this.socket?.close();
    this.socket = null;
  }
}

